cd "$GITHUB_WORKSPACE" && git fetch origin --prune && python3 - <<'PY'
import subprocess, re, os
branches=['friend/rachel','friend/monica','friend/phoebe','friend/joey','friend/chandler','friend/ross']
commits=[]
for b in branches:
    out=subprocess.check_output(['git','rev-list',f'origin/{b}'],text=True).split()
    for sha in out:
        msg=subprocess.check_output(['git','cat-file','commit',sha],text=True)
        if not re.search(r'^Friend-Message: 1$', msg, re.M): continue
        m=re.search(r'^Episode: (S\d+/E\d+)\s*$', msg, re.M)
        if not m: continue
        commits.append((sha,m.group(1)))
sources=set()
for root,_,files in os.walk('.'):
    # use origin/main tree? current workspace main updated? fetch only, not reset. Need read from origin/main via git show maybe. Simpler check file in worktree already.
    pass
# read from /tmp main worktree
import os
for root,_,files in os.walk('/tmp/main-worktree'):
    for f in files:
        if re.fullmatch(r'E\d+\.md',f):
            for line in open(os.path.join(root,f)):
                m=re.match(r'Source: (friend/\S+) @ ([0-9a-f]+)',line.strip())
                if m: sources.add(m.group(2))
missing=[c for c in commits if c[0] not in sources]
print('marked commits',len(commits),'missing',len(missing))
for m in missing: print(m)
